    lines=[]
    for c in range(W):
        cells=[i for i in range(H) if inp[i][c]==5]
        if len(cells)>=2: lines.append((c,min(cells),max(cells)))
    # pattern: for each line, find adjacent non-zero rows below/right; take contiguous band
    for c,r0,r1 in lines:
        # band: rows r0..r1, columns max(c+1,0)..W-1 restricted to non-zero rows
        band=[(inp[i][j]) for i in range(r0,r1+1) for j in range(c+1,W) if inp[i][j]!=0]
        # dedupe rows, keep distinct rows list
        rows=[]
        for i in range(r0,r1+1):
            r=[inp[i][j] for j in range(c+1,W)]
            if r!=rows[-1]: rows.append(r)
        P=rows
        if not P: continue
        # tile vertically across the line span, anchored at bottom (pattern sits at bottom of line)
        period=len(P)
        for i in range(r0,r1+1):
